"""The TT-NN calls that compute silu_glu's product and run its one program. Generated by tt-polynomial-fitter from
activations/products/silu_glu.json."""

import pytest
import torch
import ttnn
from models.common.utility_functions import is_slow_dispatch

OP_TYPE = "SILU_GLU"
ROUTE_BOARDS = ("blackhole",)


def _board(device):
    return "blackhole" if ttnn.device.is_blackhole(device) else "wormhole_b0"


def _skip_unless_routed(device):
    if _board(device) not in ROUTE_BOARDS:
        pytest.skip("this board keeps the composite")


def _device_operations(call):
    ttnn.graph.begin_graph_capture(ttnn.graph.RunMode.NORMAL)
    try:
        result = call()
    finally:
        graph = ttnn.graph.end_graph_capture()
    operations = [name for name in ttnn.graph.extract_calltrace(graph) if "DeviceOperation" in name]
    arguments = " ".join(str(argument) for node in graph for argument in node.get("arguments", []))
    return result, operations, arguments


def _operands(shape):
    generator = torch.Generator().manual_seed(0)
    return (32 * (2 * torch.rand(shape, generator=generator) - 1)).to(torch.bfloat16)


def _on_device(t, device, dtype=ttnn.bfloat16):
    return ttnn.from_torch(t, dtype=dtype, layout=ttnn.TILE_LAYOUT, device=device)


def _golden(gate, up):
    """The exact product of the leaves, from ttnn.silu_glu's golden function, in float64."""
    return ttnn.get_golden_function(ttnn.silu_glu)(gate, up).to(torch.float64)


def _assert_close(actual, golden, rtol=2.0**-7, atol=2.0**-100):
    """Within 2 BF16 steps of the golden; a result the kernel flushes to 0 is tiny in the golden too."""
    actual = actual.to(torch.float64)
    error = (actual - golden).abs()
    bad = error > atol + rtol * golden.abs()
    assert not bool(
        bad.any()
    ), f"{int(bad.sum())} of {bad.numel()} lanes off the golden; worst error {error.max().item():.3e}"


def _assert_pcc(actual, golden, bound):
    a, b = actual.to(torch.float64).flatten(), golden.to(torch.float64).flatten()
    pcc = torch.corrcoef(torch.stack([a, b]))[0, 1].item()
    assert pcc >= bound, f"PCC {pcc:.6f} against the golden, below {bound}"


@pytest.mark.parametrize("order", ["gate_first", "up_first"])
def test_multiply_with_the_leaves_activations_runs_silu_glu(device, order):
    """ttnn.multiply of BF16 operands carrying exactly the leaves' pre-activations is ttnn.silu_glu, as one program."""
    _skip_unless_routed(device)
    gate, up = _operands((1, 1, 64, 64)), _operands((1, 1, 64, 64)).flip(-1)
    expected = ttnn.to_torch(ttnn.silu_glu(_on_device(gate, device), _on_device(up, device)))
    g, u = _on_device(gate, device), _on_device(up, device)
    if order == "gate_first":
        call = lambda: ttnn.multiply(
            g, u, input_tensor_a_activations=[ttnn.UnaryWithParam(ttnn.UnaryOpType.SILU)], input_tensor_b_activations=[]
        )
    else:
        call = lambda: ttnn.multiply(
            u, g, input_tensor_a_activations=[], input_tensor_b_activations=[ttnn.UnaryWithParam(ttnn.UnaryOpType.SILU)]
        )
    out, operations, arguments = _device_operations(call)
    assert OP_TYPE in arguments and len(operations) == 1, f"launched {operations}, not one {OP_TYPE} program"
    out = ttnn.to_torch(out)
    assert torch.equal(out.view(torch.int16), expected.view(torch.int16))
    _assert_close(out, _golden(gate, up))


@pytest.mark.parametrize("output", ["l1_width_sharded", "unset"])
@pytest.mark.parametrize("order", ["gate_first", "up_first"])
def test_multiply_with_width_sharded_operands_runs_silu_glu(device, order, output):
    """L1 width-sharded operands, and an L1 width-sharded output as deepseek_v3's decode MLP asks for one (or the
    operands' placement, unset): the routed multiply is one program, in that placement, with ttnn.silu_glu's bits."""
    _skip_unless_routed(device)
    gate, up = _operands((1, 1, 32, 1024)), _operands((1, 1, 32, 1024)).flip(-1)
    expected = ttnn.to_torch(ttnn.silu_glu(_on_device(gate, device), _on_device(up, device)))
    sharded = ttnn.create_sharded_memory_config(
        (32, 128),
        core_grid=ttnn.CoreRangeSet({ttnn.CoreRange(ttnn.CoreCoord(0, 0), ttnn.CoreCoord(7, 0))}),
        strategy=ttnn.ShardStrategy.WIDTH,
        orientation=ttnn.ShardOrientation.ROW_MAJOR,
        use_height_and_width_as_shard_shape=True,
    )
    g = ttnn.from_torch(gate, dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device, memory_config=sharded)
    u = ttnn.from_torch(up, dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device, memory_config=sharded)
    kwargs = dict(memory_config=ttnn.L1_WIDTH_SHARDED_MEMORY_CONFIG) if output == "l1_width_sharded" else {}
    if order == "gate_first":
        call = lambda: ttnn.multiply(
            g,
            u,
            input_tensor_a_activations=[ttnn.UnaryWithParam(ttnn.UnaryOpType.SILU)],
            input_tensor_b_activations=[],
            **kwargs,
        )
    else:
        call = lambda: ttnn.multiply(
            u,
            g,
            input_tensor_a_activations=[],
            input_tensor_b_activations=[ttnn.UnaryWithParam(ttnn.UnaryOpType.SILU)],
            **kwargs,
        )
    out, operations, arguments = _device_operations(call)
    assert OP_TYPE in arguments and len(operations) == 1, f"launched {operations}, not one {OP_TYPE} program"
    assert out.memory_config().memory_layout == ttnn.TensorMemoryLayout.WIDTH_SHARDED
    assert out.memory_config().buffer_type == ttnn.BufferType.L1
    assert torch.equal(ttnn.to_torch(out).view(torch.int16), expected.view(torch.int16))


@pytest.mark.parametrize("case", ["bfloat8_b_output", "float32_operands", "post_activation"])
def test_multiply_keeps_binary_ng_elsewhere(device, case):
    """A multiply outside the route's dtype or activations launches no SILU_GLU program."""
    gate, up = _operands((1, 1, 64, 64)), _operands((1, 1, 64, 64))
    kwargs = dict(
        input_tensor_a_activations=[ttnn.UnaryWithParam(ttnn.UnaryOpType.SILU)], input_tensor_b_activations=[]
    )
    dtype = ttnn.float32 if case == "float32_operands" else ttnn.bfloat16
    g, u = _on_device(gate, device, dtype), _on_device(up, device, dtype)
    if case == "bfloat8_b_output":
        kwargs["dtype"] = ttnn.bfloat8_b
    if case == "post_activation":
        kwargs["activations"] = [ttnn.UnaryWithParam(ttnn.UnaryOpType.RELU)]
    out, _, arguments = _device_operations(lambda: ttnn.multiply(g, u, **kwargs))
    assert OP_TYPE not in arguments
    # The stock path computes the same product: a BFLOAT8_B output keeps about 7 bits per block.
    golden = _golden(gate, up)
    if case == "post_activation":
        golden = golden.clamp(min=0)
    _assert_pcc(ttnn.to_torch(out), golden, 0.99 if case == "bfloat8_b_output" else 0.999)


@pytest.mark.parametrize("dim", [-1])
def test_swiglu_runs_silu_glu(device, dim):
    """ttnn.swiglu over BF16 halves is ttnn.silu_glu of them, as one SILU_GLU program."""
    _skip_unless_routed(device)
    x = _operands((1, 1, 64, 128))
    gate, up = x[..., 64:], x[..., :64]
    expected = ttnn.to_torch(ttnn.silu_glu(_on_device(gate, device), _on_device(up, device)))
    out, _, arguments = _device_operations(lambda: ttnn.swiglu(_on_device(x, device), dim))
    assert OP_TYPE in arguments
    assert torch.equal(ttnn.to_torch(out).view(torch.int16), expected.view(torch.int16))


@pytest.mark.skipif(is_slow_dispatch(), reason="sub-device managers are unsupported with slow dispatch")
@pytest.mark.parametrize("dim", [-1])
def test_swiglu_keeps_its_composite_with_sub_devices_loaded(device, dim):
    """With two sub-devices loaded ttnn.swiglu keeps its unary and multiply, as on main, and launches no SILU_GLU
    program. Sub-device 0 holds every column but the last, so the split's and the unary's few cores (column-major
    from (0, 0)) and binary_ng's sub-device-0 cores all lie in it, as the composite needs."""
    _skip_unless_routed(device)
    x = _operands((1, 1, 64, 128))
    expected = ttnn.to_torch(
        ttnn.multiply(_on_device(x[..., :64], device), ttnn.swish(_on_device(x[..., 64:], device)))
    )
    grid = device.compute_with_storage_grid_size()
    first = ttnn.CoreRangeSet({ttnn.CoreRange(ttnn.CoreCoord(0, 0), ttnn.CoreCoord(grid.x - 2, grid.y - 1))})
    last = ttnn.CoreRangeSet({ttnn.CoreRange(ttnn.CoreCoord(grid.x - 1, 0), ttnn.CoreCoord(grid.x - 1, grid.y - 1))})
    manager = device.create_sub_device_manager([ttnn.SubDevice([first]), ttnn.SubDevice([last])], 0)
    device.load_sub_device_manager(manager)
    try:
        out, _, arguments = _device_operations(lambda: ttnn.swiglu(_on_device(x, device), dim))
        out = ttnn.to_torch(out)
    finally:
        device.clear_loaded_sub_device_manager()
        device.remove_sub_device_manager(manager)
    assert OP_TYPE not in arguments
    assert torch.equal(out.view(torch.int16), expected.view(torch.int16))
